      break;
    // Tab
    case 9:
      // Select on Tab if enabled
      if (ctx.resultsList.tabSelect && ctx.cursor >= 0) select(ctx, event);

      break;
    // Esc
    case 27:
      // Clear "input" value
      ctx.input.value = "";

      /**
       * @emit {clear} event on input clear
       **/
      eventEmitter("clear", ctx);

      close(ctx);
      break;
  }
};

